html:
{%- set t = frappe.get_doc("Proposal Template", doc.proposal_template) if doc.proposal_template else None -%}
{%- set c = (t.brand_color if t and t.brand_color else "#1DA7DF") -%}
{%- set logo_w = (t.logo_white if t and t.logo_white else "") -%}
{%- set logo = (t.logo if t and t.logo else frappe.db.get_value("Company", doc.company, "company_logo")) -%}
{%- set lines = doc.items | rejectattr("hide_in_proposal") | list -%}
<style>
	.print-format { margin-top: 0mm; margin-bottom: 0mm; margin-left: 0mm; margin-right: 0mm; }
	.print-format { padding: 0 !important; max-width: none !important; width: 100% !important; font-family: "Helvetica Neue", Arial, sans-serif; color: #222; font-size: 10.5pt; }
	.ep { position: relative; width: 100%; page-break-after: always; }
	.ep.last { page-break-after: auto; }
	.ep-cover { height: 296mm; overflow: hidden; background: {{ c }}; color: #fff; }
	.ep-cover .top { position: absolute; top: 14mm; left: 6mm; right: 16mm; border-bottom: 1px solid rgba(255,255,255,.8); height: 16mm; }
	.ep-cover .top img { position: absolute; right: 0; top: -4mm; height: 17mm; }
	.ep-cover .quote { position: absolute; top: 62mm; left: 10mm; font-size: 70pt; line-height: 1; font-family: Georgia, serif; opacity: .85; }
	.ep-cover .title { position: absolute; top: 92mm; left: 10mm; width: 150mm; font-size: 27pt; font-weight: 300; line-height: 1.2; text-transform: uppercase; }
	.ep-cover .meta { position: absolute; top: 135mm; left: 10mm; font-size: 11.5pt; line-height: 1.9; }
	.ep-cover .side { position: absolute; top: 120mm; left: 140mm; width: 120mm; font-size: 9pt; letter-spacing: 2.5pt; text-transform: uppercase;
		-webkit-transform: rotate(-90deg); transform: rotate(-90deg); }
	.ep-band { background: {{ c }}; color: #fff; padding: 22mm 14mm 9mm; font-size: 21pt; text-transform: uppercase; }
	.ep-body { padding: 9mm 14mm 10mm; }
	.ep-body p { margin: 0 0 3mm; line-height: 1.45; }
	.ep-h { color: {{ c }}; font-size: 19pt; font-weight: bold; margin: 5mm 0 4mm; text-transform: uppercase; }
	.ep-why { width: 100%; border-collapse: separate; border-spacing: 0 3mm; }
	.ep-why td { padding: 2.5mm 3mm; vertical-align: middle; font-size: 11pt; }
	.ep-why tr.alt td.txt { background: #d6eefa; }
	.ep-why td.ico { width: 9mm; padding: 0; }
	.ep-chk { display: inline-block; width: 7mm; height: 7mm; line-height: 7mm; border-radius: 50%; background: {{ c }}; color: #fff; text-align: center; font-size: 10pt; }
	.ep-refs img { width: 100%; }
	.ep-table { width: 100%; border-collapse: collapse; margin-top: 4mm; }
	.ep-table th { background: {{ c }}; color: #fff; font-weight: bold; padding: 3mm; text-align: left; border: 1px solid {{ c }}; }
	.ep-table th.amt { background: #1f3a5f; border-color: #1f3a5f; }
	.ep-table td { border: 1px solid #b9d7e8; padding: 3mm; vertical-align: top; }
	.ep-table .num { text-align: right; white-space: nowrap; }
	.ep-table tr.tot td { background: #d6eefa; color: #1f3a5f; }
	.ep-table tr.grand td { background: {{ c }}; color: #fff; font-weight: bold; border-color: {{ c }}; }
	.ep-terms h4 { color: {{ c }}; font-size: 10.5pt; font-weight: normal; margin: 3mm 0 1mm; }
	.ep-terms p { margin: 0 0 1mm; line-height: 1.4; }
	.ep-sign { width: 100%; margin-top: 12mm; }
	.ep-sign td { width: 50%; vertical-align: top; line-height: 2.1; }
	.ep-sign .h { color: {{ c }}; margin-bottom: 3mm; }
</style>

<div class="ep ep-cover">
	<div class="top">{% if logo_w %}<img src="{{ logo_w }}">{% endif %}</div>
	<div class="quote">&ldquo;</div>
	<div class="title">{% for l in (t.cover_title if t and t.cover_title else "Technical & Financial Proposal").split("\n") %}{{ l | e }}{% if not loop.last %}<br>{% endif %}{% endfor %}</div>
	<div class="meta">
		{% if doc.contact_name %}Submitted to: {{ doc.contact_name | e }}<br>{% endif %}
		Company name: {{ (doc.customer_name or "") | e }}<br>
		{% if doc.prepared_by_name %}Prepared by: {{ doc.prepared_by_name | e }}<br>{% endif %}
		Date: {{ frappe.utils.format_date(doc.proposal_date, "d MMMM y") }}
		{% if doc.proposal_type == "Changes only" %}<br>Change proposal to {{ doc.revision_of }}{% endif %}
	</div>
	{% if t and t.side_text %}<div class="side">{{ t.side_text | e }}</div>{% endif %}
</div>

{% if t and (t.about or t.why_points) %}
<div class="ep">
	<div class="ep-band">{{ (t.about_title or "") | e }}</div>
	<div class="ep-body">
		{% for p in (t.about or "").split("\n") if p.strip() %}<p>{{ p | e }}</p>{% endfor %}
		{% if t.why_points %}
		<div class="ep-h">{{ (t.why_title or "Why us?") | e }}</div>
		<table class="ep-why">
			{% for p in t.why_points.split("\n") if p.strip() %}
			<tr class="{{ 'alt' if loop.index is odd else '' }}">
				<td class="ico">{% if t.check_icon %}<img src="{{ t.check_icon }}" style="width:7mm">{% else %}<span class="ep-chk">&#10003;</span>{% endif %}</td>
				<td class="txt">{{ p | e }}</td>
			</tr>
			{% endfor %}
		</table>
		{% endif %}
	</div>
</div>
{% endif %}

{% if t and t.references_image %}
<div class="ep ep-refs">
	<div class="ep-band">{{ (t.references_title or "Sample client references") | e }}</div>
	<div class="ep-body"><img src="{{ t.references_image }}"></div>
</div>
{% endif %}

<div class="ep">
	<div class="ep-band">{{ (t.prices_title if t and t.prices_title else "Prices & Payment Schedule") | e }}</div>
	<div class="ep-body">
		<table class="ep-table">
			<thead><tr>
				<th style="width:52%">Description</th><th style="width:14%">Qty</th>
				<th class="num" style="width:16%">Unit Price</th><th class="num amt" style="width:18%">Amount {{ doc.currency }}</th>
			</tr></thead>
			<tbody>
			{% for r in lines %}
				<tr>
					<td>{{ (r.description or r.item_name or r.item_code or "") | e }}</td>
					<td>{{ r.qty|int if r.qty == r.qty|int else r.qty }} {{ ((r.uom or "") | lower) if r.uom and r.uom != "Nos" else "" }}</td>
					<td class="num">{{ frappe.utils.fmt_money(r.rate, precision=2 if r.rate != r.rate|int else 0) }}</td>
					<td class="num">{{ frappe.utils.fmt_money(r.amount, precision=2 if r.amount != r.amount|int else 0) }}</td>
				</tr>
			{% endfor %}
			{% if doc.tax_amount %}
				<tr class="tot"><td colspan="3">Total without {{ (doc.tax_label or "VAT").split(" ")[-1] | e }}</td><td class="num">{{ frappe.utils.fmt_money(doc.total, currency=doc.currency) }}</td></tr>
				<tr class="tot"><td colspan="3">{{ (doc.tax_label or "VAT") | e }}</td><td class="num">{{ frappe.utils.fmt_money(doc.tax_amount, currency=doc.currency) }}</td></tr>
				<tr class="grand"><td colspan="3">Total including {{ (doc.tax_label or "VAT").split(" ")[-1] | e }}</td><td class="num">{{ frappe.utils.fmt_money(doc.grand_total, currency=doc.currency) }}</td></tr>
			{% else %}
				<tr class="grand"><td colspan="3">Total</td><td class="num">{{ frappe.utils.fmt_money(doc.grand_total, currency=doc.currency) }}</td></tr>
			{% endif %}
			</tbody>
		</table>
		{% if doc.valid_till %}<p style="margin-top:4mm;color:#666">Valid till {{ frappe.utils.format_date(doc.valid_till, "d MMMM y") }}</p>{% endif %}
	</div>
</div>

<div class="ep last">
	<div class="ep-band">Terms and Conditions</div>
	<div class="ep-body ep-terms">
		{{ doc.terms or "" }}
		<table class="ep-sign"><tr>
			<td><div class="h">Concurrence</div><b>{{ doc.company | e }}</b><br>Name:<br>Signature:<br>Title:<br>Date:</td>
			<td><div class="h">&nbsp;</div><b>{{ (doc.customer_name or "Client Name:") | e }}</b><br>Name:<br>Signature:<br>Title:<br>Date:</td>
		</tr></table>
	</div>
</div>
